import json, re, sys
from lightrag.knowledge_graph import load_prebuilt_graph, profile_knowledge_graph, chunk_markdown, PDPA_GRAPH_JSON, PDPA_MD
from lightrag.vector_index import VectorIndex
G = load_prebuilt_graph(PDPA_GRAPH_JSON); P = profile_knowledge_graph(G); _, store = chunk_markdown(PDPA_MD)
ix = VectorIndex(); ix.profiles = P; ix.chunk_store = store
TH="๐๑๒๓๔๕๖๗๘๙"
def secid(s): return "sec_"+"".join(str(TH.index(c)) if c in TH else c for c in s.replace("มาตรา","").strip())
PEN=("โทษ","ปรับ","จำคุก","สินไหม","ค่าเสียหาย")
cache={}
def S(q,k=5):
    q=q.strip()
    if not q: return []
    if q not in cache: cache[q]=[c["section_id"] for c in ix.search_chunks(q,top_k=8)]
    return cache[q][:k]
def add(main,extra,n):
    out=list(main)
    for c in extra:
        if len(out)>=len(main)+n: break
        if c not in out: out.append(c)
    return out
def variants(kw):
    low,high=kw["low_level"],kw["high_level"]; allk=low+high
    full=" ".join(low)+" "+" ".join(high)
    pen=[k for k in dict.fromkeys(allk) if any(w in k for w in PEN)]
    v={"V0":S(full,5),"T7":S(full,7),"T8":S(full,8)}
    v["P2"]=add(S(full,5),S(" ".join(pen),8),2) if pen else v["V0"]
    v["P3"]=add(S(full,5),S(" ".join(pen),8),3) if pen else v["V0"]
    return v,bool(pen)
out=[]
for it in ITEMS:
    row={"id":it["id"],"gold":it["gold"],"set":it["set"],"arms":{}}
    for arm,a in it["arms"].items():
        ns={(re.match(r"\[hop\d\] \S+ \S+ (\S+?):",l) or [None,None])[1] for l in a["exp"]}
        base=ns|set(a["profiles"][:8]); vs,haspen=variants(a["kw"])
        row["arms"][arm]={"haspen":haspen,**{k:{"chunks":c,"gold_ctx":[g for g in it["gold"] if g in base|{secid(x) for x in c}]} for k,c in vs.items()}}
    out.append(row); print("done",it["id"],file=sys.stderr,flush=True)
print("RESULT "+json.dumps(out,ensure_ascii=False))
